/* global describe, it, expect, vi, beforeEach, afterEach -- vitest globals (globals: true); declared for `eslint .` */
/**
 * Characterization tests for src/pages/editor/utils/codeImporter.ts (importCodeToElement and
 * validateCodeSyntax): the complete ImportResult (element tree, ids, ordering, styles / layout, warnings,
 * errors and statuses) for every case in codeImporter.fixtures.ts.
 *
 * codeImporter.golden.json was captured once from the unmodified module, before it was split into
 * src/pages/editor/utils/code-import/, and is never regenerated by this test.
 *
 * Determinism: generated ids come from Math.random and Date.now. Math.random is replaced by a counter
 * sequence and the clock is fixed at FIXED_NOW, both reset before every case.
 */
import { fileURLToPath } from "node:url";
import { join, dirname } from "node:path";
import { readFileSync } from "node:fs";
import * as importer from "../../src/pages/editor/utils/codeImporter";
import { FIXED_NOW, IMPORT_CASES, VALIDATION_CASES } from "./codeImporter.fixtures";

const here = dirname(fileURLToPath(import.meta.url));
const golden: Record<string, unknown> = JSON.parse(readFileSync(join(here, "codeImporter.golden.json"), "utf8"));

let n = 0;
beforeEach(() => {
  n = 0;
  vi.useFakeTimers({ now: FIXED_NOW, toFake: ["Date"] });
  vi.spyOn(Math, "random").mockImplementation(() => ((n++ * 7919) % 1000) / 1000 + 0.0001);
});
afterEach(() => {
  vi.useRealTimers();
  vi.restoreAllMocks();
});

const json = (v: unknown) => JSON.parse(JSON.stringify(v === undefined ? "[undefined]" : v));

describe("codeImporter public surface", () => {
  it("exports exactly importCodeToElement and validateCodeSyntax as functions", () => {
    expect(Object.keys(importer).sort()).toEqual(["importCodeToElement", "validateCodeSyntax"]);
    expect(typeof importer.importCodeToElement).toBe("function");
    expect(typeof importer.validateCodeSyntax).toBe("function");
  });
  it("the golden covers every case", () => {
    expect(Object.keys(golden).sort()).toEqual([
      ...Object.keys(IMPORT_CASES).map((k) => `import:${k}`),
      ...Object.keys(VALIDATION_CASES).map((k) => `validate:${k}`),
    ].sort());
  });
});

describe("importCodeToElement", () => {
  it.each(Object.keys(IMPORT_CASES))("%s", (name) => {
    const c = IMPORT_CASES[name];
    expect(json(importer.importCodeToElement(c.code, c.options as any))).toEqual(golden[`import:${name}`]);
  });
});

describe("validateCodeSyntax", () => {
  it.each(Object.keys(VALIDATION_CASES))("%s", (name) => {
    expect(json(importer.validateCodeSyntax(VALIDATION_CASES[name]))).toEqual(golden[`validate:${name}`]);
  });
});
